// MINI INTÉRPRETE: texto → fichas (léxico) → árbol (sintaxis) → chequeo (semántica) → resultado
function leer(texto) {                                   // 1) análisis léxico: caracteres → fichas
  const fichas = [], re = /\s*(?:(\d+(?:\.\d+)?)|([a-z_]\w*)|(.))/gy;
  let m;
  while (re.lastIndex < texto.length && (m = re.exec(texto))) {
    if (m[1] !== undefined) fichas.push({ tipo: "num", valor: Number(m[1]) });
    else if (m[2] !== undefined) fichas.push({ tipo: "id", nombre: m[2] });
    else if ("+-*/()".includes(m[3])) fichas.push({ tipo: m[3] });
    else throw new Error(`carácter inesperado «${m[3]}»`);
  }
  return fichas;
}

function analizar(fichas) {                              // 2) análisis sintáctico: fichas → árbol (AST)
  let i = 0;
  const mirar = () => fichas[i]?.tipo, tomar = () => fichas[i++];
  function expresion() {                                 // suma y resta: la precedencia más baja
    let izq = termino();
    while (mirar() === "+" || mirar() === "-") izq = { op: tomar().tipo, izq, der: termino() };
    return izq;
  }
  function termino() {                                   // multiplicación y división: se resuelven antes
    let izq = unario();
    while (mirar() === "*" || mirar() === "/") izq = { op: tomar().tipo, izq, der: unario() };
    return izq;
  }
  function unario() { return mirar() === "-" ? (tomar(), { op: "neg", der: unario() }) : atomo(); }
  function atomo() {
    const f = tomar();
    if (!f) throw new Error("la expresión termina antes de tiempo");
    if (f.tipo === "num") return { num: f.valor };
    if (f.tipo === "id") return { id: f.nombre };
    if (f.tipo === "(") {
      const e = expresion();
      if (tomar()?.tipo !== ")") throw new Error("falta cerrar el paréntesis");
      return e;
    }
    throw new Error(`no esperaba «${f.tipo}» acá`);
  }
  const arbol = expresion();
  if (i < fichas.length) throw new Error(`sobra «${fichas[i].tipo}» al final`);
  return arbol;
}

function chequear(n, conocidos) {                        // 3) análisis semántico: ¿tiene sentido?
  if (n.id !== undefined && !(n.id in conocidos)) throw new Error(`«${n.id}» no está definido`);
  if (n.op === "/" && n.der.num === 0) throw new Error("división por cero escrita en el código");
  for (const hijo of [n.izq, n.der]) if (hijo) chequear(hijo, conocidos);
}

function evaluar(n, entorno) {                           // 4) ejecutar: recorrer el árbol de abajo hacia arriba
  if (n.num !== undefined) return n.num;
  if (n.id !== undefined) return entorno[n.id];
  if (n.op === "neg") return -evaluar(n.der, entorno);
  const a = evaluar(n.izq, entorno), b = evaluar(n.der, entorno);
  return n.op === "+" ? a + b : n.op === "-" ? a - b : n.op === "*" ? a * b : a / b;
}

function correr(texto, entorno = {}) {
  try {
    const arbol = analizar(leer(texto));
    chequear(arbol, entorno);
    return evaluar(arbol, entorno);
  } catch (e) { return "error: " + e.message; }
}

