// COMPILADOR de juguete: el mismo árbol, pero en vez de ejecutarlo se traduce a instrucciones de una máquina de pila
const fichas = t => t.match(/\d+(?:\.\d+)?|[a-z_]\w*|[-+*/()]/g);        // léxico (versión compacta)
function arbol(texto) {                                                  // sintaxis (versión compacta)
  const f = fichas(texto); let i = 0;
  const suma = () => { let n = prod(); while ("+-".includes(f[i] ?? "#")) { const op = f[i++]; n = { op, izq: n, der: prod() }; } return n; };
  const prod = () => { let n = atomo(); while ("*/".includes(f[i] ?? "#")) { const op = f[i++]; n = { op, izq: n, der: atomo() }; } return n; };
  const atomo = () => {
    const x = f[i++];
    if (x === "(") { const n = suma(); i++; return n; }
    if (x === "-") return { op: "neg", der: atomo() };
    return /^\d/.test(x) ? { num: Number(x) } : { id: x };
  };
  return suma();
}

const calc = (op, a, b) => ({ "+": a + b, "-": a - b, "*": a * b, "/": a / b, neg: -b })[op];
function plegar(n) {                       // optimización: lo que ya se puede calcular, se calcula ahora y no cada vez
  if (n.num !== undefined || n.id !== undefined) return n;
  const izq = n.izq && plegar(n.izq), der = plegar(n.der);
  if (der.num !== undefined && (!izq || izq.num !== undefined)) return { num: calc(n.op, izq?.num, der.num) };
  return { op: n.op, izq, der };
}

function generar(n, out = []) {            // generación de código: recorrer el árbol y emitir instrucciones
  if (n.num !== undefined) out.push("PUSH " + n.num);
  else if (n.id !== undefined) out.push("LOAD " + n.id);
  else {
    if (n.izq) generar(n.izq, out);
    generar(n.der, out);
    out.push({ "+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", neg: "NEG" }[n.op]);
  }
  return out;
}

function maquina(programa, entorno) {      // la «CPU» de juguete: una pila y siete instrucciones
  const pila = [];
  for (const ins of programa) {
    const [op, arg] = ins.split(" ");
    if (op === "PUSH") pila.push(Number(arg));
    else if (op === "LOAD") pila.push(entorno[arg]);
    else if (op === "NEG") pila.push(-pila.pop());
    else { const b = pila.pop(), a = pila.pop(); pila.push(op === "ADD" ? a + b : op === "SUB" ? a - b : op === "MUL" ? a * b : a / b); }
  }
  return pila.pop();
}

const texto = "kilos * (2 + 3) + 10 * 10";
const sinOptimizar = generar(arbol(texto));
const optimizado = generar(plegar(arbol(texto)));
console.log(`«${texto}» sin optimizar (${sinOptimizar.length} instrucciones):\n  ${sinOptimizar.join("; ")}`);
console.log(`optimizado (${optimizado.length} instrucciones):\n  ${optimizado.join("; ")}`);
console.log("resultado con kilos = 4:", maquina(sinOptimizar, { kilos: 4 }), "y", maquina(optimizado, { kilos: 4 }));

// El mismo cálculo de tres maneras. Árbol de «kilos * (2 + 3) + 10 * 10», recorrido una y otra vez:
const arbol = { op: "+", izq: { op: "*", izq: { id: "kilos" }, der: { op: "+", izq: { num: 2 }, der: { num: 3 } } },
                         der: { op: "*", izq: { num: 10 }, der: { num: 10 } } };
function caminar(n, e) {                                   // a) intérprete de árbol: decide en cada vuelta qué hacer
  if (n.num !== undefined) return n.num;
  if (n.id !== undefined) return e[n.id];
  const a = caminar(n.izq, e), b = caminar(n.der, e);
  return n.op === "+" ? a + b : n.op === "*" ? a * b : NaN;
}
const generado = new Function("kilos", "return kilos * (2 + 3) + 10 * 10"); // b) código generado una vez y compilado por el motor
