function medir(nombre, f) {
  f(1);                                                    // una pasada de calentamiento
  const t0 = performance.now(); let suma = 0;
  for (let k = 0; k < VUELTAS; k++) suma += f(k);
  console.log(nombre.padEnd(22), Math.round(performance.now() - t0), "ms   (suma de control:", suma + ")");
}
